ading .eyebrow{font-size:8px;margin-bottom:6px}.draw-panel{padding:18px 0 17px;border-bottom:1px solid #ffffff12}.draw-count{border:1px solid #3c4639;border-radius:3px;padding:5px 7px;font-size:8px;letter-spacing:.7px;color:#bdc6ae}.panel-copy{font-size:10px;line-height:1.55;color:#a5a99a;margin:9px 0 12px;max-width:300px}.draw-button{width:100%;height:54px;border:1px solid #839873;background:linear-gradient(110deg,#3b4c36,#2e3b2c);border-radius:4px;color:#f2f1e5;display:flex;align-items:center;text-align:left;padding:0 13px;gap:11px;cursor:pointer;transition:.2s;box-shadow:inset 0 1px #ffffff12}.draw-button:hover:not(:disabled){filter:brightness(1.15);transform:translateY(-1px)}.draw-button:disabled{opacity:.42;cursor:not-allowed}.draw-symbol{display:grid;place-items:center;color:#e8c77d;font-size:17px;width:28px;height:28px;border:1px solid #c9b47d70;border-radius:50%}.draw-button span:nth-child(2){display:grid;gap:3px}.draw-button b{font-size:10px;letter-spacing:1px}.draw-button small{font-size:8px;color:#c7c9b8;letter-spacing:.8px}.draw-button kbd{margin-left:auto;color:#bec4b5;border:1px solid #ffffff3b;background:#ffffff0b;padding:4px 6px;border-radius:3px;font:8px var(--sans}.draw-result{height:0;opacity:0;overflow:hidden;transition:.25s;text-align:center;color:#e4d3a9;font-size:10px;letter-spacing:.3px}.draw-result.active{height:24px;padding-top:8px;opacity:1}.squad-panel{padding:17px 0 15px;flex:1;min-height:185px}.squad-heading h2{display:flex;align-items:center;gap:8px}.squad-heading h2 span{font:500 9px var(--sans);color:#a9b896;border:1px solid #475242;padding:3px 6px;border-radius:9px}.sort-button{border:1px solid #394437;background:#ffffff05;color:#bdc6ae;width:27px;height:26px;border-radius:4px;font-size:16px;cursor:pointer}.roster{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:12px}.unit-card{min-width:0;height:103px;position:relative;border:1px solid #3a4438;border-radius:5px;background:linear-gradient(145deg,#29332a,