b{display:block;color:#e6d39c;font-size:14px;margin-top:3px}.round-button{height:38px;width:100%;border:0;border-radius:3px;background:#b8c99a;color:#172017;display:flex;align-items:center;justify-content:center;gap:12px;font:700 9px var(--sans);letter-spacing:1.3px;cursor:pointer;transition:.2s}.round-button:hover:not(:disabled){background:#d0dcae;transform:translateY(-1px)}.round-button:disabled{opacity:.5;cursor:default}.round-button i{font-style:normal;font-size:15px}.site-footer{height:57px;display:flex;align-items:center;justify-content:space-between;color:#798173;font-size:8px;letter-spacing:1px}.site-footer>span:first-child{color:#b4c396;font-size:13px}.site-footer b{font:700 8px var(--sans);letter-spacing:1.2px;margin-left:6px;color:#89937e}.site-footer i{font-style:normal;color:#b8c894;margin:0 5px}.modal-backdrop{position:fixed;inset:0;z-index:5;display:grid;place-items:center;background:#080b09c9;backdrop-filter:blur(7px);opacity:0;pointer-events:none;transition:.2s;padding:18px}.modal-backdrop.open{opacity:1;pointer-events:auto}.guide-modal{position:relative;width:min(460px,100%);background:#1b241c;border:1px solid #667558;border-radius:7px;padding:33px 35px 28px;box-shadow:0 24px 90px #000b}.guide-modal h2{font:700 29px var(--serif);margin:0 0 20px}.guide-modal ol{padding-left:20px;margin:0;display:grid;gap:14px;color:#b3b8a8;font-size:12px;line-height:1.6}.guide-modal li::marker{color:#c7ce9e;font-weight:bold}.guide-modal li b{color:#e4e6d7}.modal-close{position:absolute;right:14px;top:10px;background:transparent;border:0;color:#aab29e;font-size:23px;cursor:pointer}.modal-start{width:100%;height:42px;margin-top:23px;border:0;border-radius:3px;background:#b8c99a;color:#192119;font:700 10px var(--sans);letter-spacing:1px;cursor:pointer}.modal-start span{margin-left:8px;font-size:15px}
