(() => {
  const canvas = document.querySelector('#battlefield');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const chars = [
    {name:'Tanjiro', color:'#518b66', hair:'#251d1b', accent:'#cf655b', mark:'water', symbol:'水', hp:0},
    {name:'Zenitsu', color:'#d9a83b', hair:'#edc75d', accent:'#674336', mark:'thunder', symbol:'雷', hp:0},
    {name:'Inosuke', color:'#7796a1', hair:'#9baca5', accent:'#bba1a0', mark:'beast', symbol:'獣', hp:0},
    {name:'Nezuko', color:'#bb716b', hair:'#231b21', accent:'#dca2a1', mark:'flower', symbol:'花', hp:0},
    {name:'Giyu', color:'#59758e', hair:'#181b21', accent:'#b44f49', mark:'water', symbol:'水', hp:0}
  ];
  const cols=9, rows=7;
  const route=[{x:0,y:3},{x:1,y:3},{x:2,y:3},{x:2,y:2},{x:2,y:1},{x:3,y:1},{x:4,y:1},{x:5,y:1},{x:5,y:2},{x:5,y:3},{x:5,y:4},{x:5,y:5},{x:6,y:5},{x:7,y:5},{x:7,y:4},{x:7,y:3},{x:8,y:3}];
  const pathSet=new Set(route.map(p=>`${p.x},${p.y}`));
  let units=[], enemies=[], projectiles=[], selected=null, nextId=1, gold=5, health=20, wave=1, running=false, spawned=0, total=6, spawnTimer=0, last=0, frame=0, soundOn=false, gameOver=false, sorted=false, cellSize=50, ox=0, oy=0, boardW=0, boardH=0, toastTimer, fx=[];
  const unitStats=[{range:2.55,rate:1.04,damage:12},{range:2.35,rate:.73,damage:9},{range:1.7,rate:.58,damage:17},{range:2.1,rate:.88,damage:11},{range:2.8,rate:1.12,damage:13}];
  const unitCount=()=>units.length;
  const rankName=(r)=>['','MIZUNOTO','MIZUNOE','KANOTO','KANOE'][Math.min(4,r)]||'HASHIRA';
  const money=(n)=>{gold+=n;$('#goldCount').textContent=gold;updateButtons()};
  function updateButtons(){ $('#drawButton').disabled=gold<1||gameOver; $('#roundButton').disabled=running; $('#roundButton').querySelector('span').textContent=gameOver?'PLAY AGAIN':running?'WAVE IN PROGRESS':'BEGIN WAVE'; $('#roundStatus').textContent=gameOver?'The gate has fallen':running?'Demons approaching':wave===1?'Ready when you are':`Wave ${wave-1} survived`; $('#nextWave').textContent=String(wave).padStart(2,'0');$('#drawCount').textContent=`${gold} ${gold===1?'DRAW':'DRAWS'}`; }
  function announce(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
  function rankLabel(r){return r===1?'MIZUNOTO':r===2?'MIZUNOE':r===3?'KANOTO':'HASHIRA';}
  function portraitMarkup(ch,rank=1){return `<svg class="portrait" viewBox="0 0 56 56" aria-hidden="true"><circle cx="28" cy="28" r="26" fill="#182019" stroke="${ch.color}" stroke-width="2"/><path d="M11 45Q14 31 28 31t17 14v5H11z" fill="${ch.color}"/><path d="M16 40l12 10 12-10-4 10H20z" fill="${ch.accent}"/><ellipse cx="28" cy="24" rx="13" ry="15" fill="#e3b99e"/><path d="M15 22Q13 7 28 8q14 1 14 14l-7-7-5 5-6-5-8 9z" fill="${ch.hair}"/><path d="M20 24h4m8 0h4" stroke="#342b2b" stroke-width="2" stroke-linecap="round"/><path d="M25 31q3 2 6 0" fill="none" stroke="#9b6157" stroke-width="1.5"/><path d="M14 44l9-5 5 7 5-7 9 5" fill="none" stroke="#f1e8d1" stroke-opacity=".75" stroke-width="1.5"/><text x="28" y="54" text-anchor="middle" font-size="6" font-family="sans-serif" fill="#f2d89a">${rank>1?'✦'.repeat(Math.min(rank-1,3)):''}</text></svg>`}
  function updateRoster(){
    const roster=$('#roster');roster.innerHTML='';const ordered=[...units].sort((a,b)=>sorted?(b.rank-a.rank||a.name.localeCompare(b.name)):(a.id-b.id));
    ordered.forEach(u=>{const ch=chars[u.type],card=document.createElement('button');card.className=`unit-card ${u.x!==null?'deployed':''} ${selected===u.id?'selected':''}`;card.innerHTML=`${u.x!==null?'<span class="deployed-tag">ON FIELD</span>':''}<span class="rank-pips">${'<i></i>'.repeat(Math.max(0,u.rank-1))}</span>${portraitMarkup(ch,u.rank)}<strong>${u.name}</strong><small>${rankLabel(u.rank)}</small>`;card.setAttribute('aria-label',`${u.name}, ${rankLabel(u.rank)}${u.x!==null?', deployed':''}`);card.onclick=()=>{selected=selected===u.id?null:u.id;updateRoster();$('#canvasTip').classList.toggle('hidden',selected===null);if(selected!==null)announce(u.x===null?'Choose an open grass tile to deploy.':'Choose a grass tile to reposition.');};roster.appendChild(card)});
    $('#rosterEmpty').style.display=units.length?'none':'flex';$('#roster').style.display=units.length?'grid':'none';$('#unitCount').textContent=unitCount();
  }
  function addUnit(type){units.push({id:nextId++,type,name:chars[type].name,rank:1,x:null,y:null,cooldown:0,kills:0});let merged=true;while(merged){merged=false;for(let t=0;t<chars.length&&!merged;t++)for(let r=1;r<4&&!merged;r++){const group=units.filter(u=>u.type===t&&u.rank===r);if(group.length>=3){const trio=group.slice(0,3);const deployed=trio.filter(u=>u.x!==null).sort((a,b)=>a.id-b.id);const base=deployed[0]||trio[0];for(const u of trio)if(u!==base)units=units.filter(x=>x.id!==u.id);base.rank++;base.cooldown=0;selected=base.id;fx.push({x:base.x===null?4.5:base.x,y:base.y===null?3:base.y,time:1.25,kind:'merge',color:chars[t].color});announce(`${base.name} evolved to ${rankLabel(base.rank)}!`);merged=true;break}}}updateRoster();updateButtons();}
  function placeUnit(x,y){const u=units.find(v=>v.id===selected);if(!u)return;const occupant=units.find(v=>v.x===x&&v.y===y);if(occupant&&occupant.id===u.id){selected=null;updateRoster();$('#canvasTip').classList.add('hidden');return}if(occupant){if(u.x!==null){const oldX=u.x,oldY=u.y;occupant.x=oldX;occupant.y=oldY;u.x=x;u.y=y;announce(`${u.name} and ${occupant.name} switched places.`)}else{announce('That tile is occupied. Choose an open tile.');return}}else{u.x=x;u.y=y;announce(`${u.name} deployed to the pass.`)}selected=null;updateRoster();$('#canvasTip').classList.add('hidden');}
  function drawPortrait(c,x,y,r,ch,rank=1){
    c.save();c.translate(x,y);c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.fillStyle='#19221a';c.fill();c.lineWidth=Math.max(1.5,r*.09);c.strokeStyle=ch.color;c.stroke();c.beginPath();c.arc(0,0,r-2,-Math.PI*.85,-Math.PI*.2);c.strokeStyle=ch.accent;c.lineWidth=Math.max(1,r*.07);c.stroke();
