  function update(dt){frame+=dt*1000;fx=fx.filter(f=>(f.time-=dt)>0);if(!running)return;
    if(spawned<total){spawnTimer-=dt;if(spawnTimer<=0){const elite=wave%4===0&&spawned===total-1;const hp=(28+wave*8)*(elite?2.3:1);enemies.push({progress:0,hp,hpMax:hp,speed:(.55+wave*.018)*(elite?.75:1),elite});spawned++;spawnTimer=1.12;}}
    enemies.forEach(e=>{e.progress+=e.speed*dt;if(e.progress>=route.length-1){health=Math.max(0,health-(e.elite?4:2));e.hp=0;updateHealth();}});
    units.filter(u=>u.x!==null).forEach(u=>{u.cooldown-=dt;const s=unitStats[u.type],at=cellCenter(u.x,u.y);if(u.cooldown<=0){let target=null,best=Infinity;for(const e of enemies){if(e.hp<=0)continue;const p=enemyPosition(e),dx=(p.x-at.x)/cellSize,dy=(p.y-at.y)/cellSize,d=Math.hypot(dx,dy);if(d<=s.range&&e.progress>best){target=e;best=e.progress}}if(target){u.cooldown=s.rate/Math.pow(1.38,u.rank-1);const p=enemyPosition(target),damage=s.damage*Math.pow(1.9,u.rank-1);target.hp-=damage;projectiles.push({x:at.x,y:at.y,tx:p.x,ty:p.y,t:0,duration:.16,color:chars[u.type].accent,r:2.6,damage,target});}}});
    projectiles=projectiles.filter(p=>{p.t+=dt;const t=Math.min(1,p.t/p.duration);p.x+=(p.tx-p.x)*Math.min(1,dt*17);p.y+=(p.ty-p.y)*Math.min(1,dt*17);return t<1});
    enemies=enemies.filter(e=>{if(e.hp<=0){if(!e.dead){e.dead=true;money(0)}return false}return e.progress<route.length-1});
    if(health<=0){running=false;gameOver=true;$('#phaseText').textContent='THE GATE HAS FALLEN';announce('The village gate has fallen. Start over and try a new formation.');updateButtons();return}
    $('#waveCount').textContent=`${spawned} / ${total}`;$('#waveProgress').style.width=`${Math.min(100,(spawned/total)*100)}%`;
    if(spawned===total&&enemies.length===0){running=false;money(2+Math.floor(wave/2));$('#phaseText').textContent='PREPARATION PHASE';$('#roundStatus').textContent=`Wave ${wave} cleared · +${2+Math.floor(wave/2)} wisteria`;$('#waveFlash').textContent='WAVE CLEARED';$('#waveFlash').classList.add('show');setTimeout(()=>$('#waveFlash').classList.remove('show'),1350);wave++;if(wave>8){gameOver=true;$('#roundStatus').textContent='The pass is safe';$('#phaseText').textContent='DAWN HAS COME';announce('The Corps held the pass through all eight waves!');}updateButtons()}
  }
  function updateHealth(){const p=health/20*100;$('#healthBar').style.width=`${p}%`;$('#healthBar').style.background=health<=6?'#d57c6a':'#b4c58e';$('#healthText').textContent=`${health} / 20`}
  function loop(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;update(dt);drawBoard();requestAnimationFrame(loop)}
