  function drawSlayer(){if(gold<1||gameOver)return;money(-1);const type=Math.floor(Math.random()*chars.length);addUnit(type);const unit=units.findLast(u=>u.type===type);$('#drawResult').textContent=`✦  ${unit.name} joined the Corps`;$('#drawResult').classList.add('active');setTimeout(()=>$('#drawResult').classList.remove('active'),2000);$('#canvasTip').classList.remove('hidden')}
